from typing import List, Union

class LookupErr:
    def __init__(self, NotFound: str = "", EmptyCollection: bool = False):
        self.NotFound = NotFound
        self.EmptyCollection = EmptyCollection

def safeSum(arr: List[int]) -> Union[int, LookupErr]:
    if len(arr) == 0:
        return LookupErr(EmptyCollection=True)

    q = 0
    for p in arr:
        q = q + p
    return q

def main():
    test_cases = [
        [1, 2, 3, 4, 5],
        [],
        [0, 0, 0, 0],
        [-5, 10, -3, 8],
        [1000000, -1000000]
    ]

    for i, arr in enumerate(test_cases):
        result = safeSum(arr)
        if isinstance(result, LookupErr):
            print(f"Test {i+1}: Error - EmptyCollection={result.EmptyCollection}")
        else:
            print(f"Test {i+1}: {result}")

if __name__ == "__main__":
    main()

