#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    char* NotFound;
    bool EmptyCollection;
} LookupErr;

typedef struct {
    bool is_error;
    union {
        int64_t value;
        LookupErr error;
    } data;
} Result_i64_LookupErr;

Result_i64_LookupErr safeSum(int64_t* arr, size_t len) {
    if (len == 0) {
        LookupErr err = { .NotFound = NULL, .EmptyCollection = true };
        Result_i64_LookupErr result = { .is_error = true, .data.error = err };
        return result;
    }
    int64_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum += arr[i];
    }
    Result_i64_LookupErr result = { .is_error = false, .data.value = sum };
    return result;
}

void print_result(Result_i64_LookupErr r) {
    if (r.is_error) {
        if (r.data.error.EmptyCollection) {
            printf("Error: EmptyCollection\n");
        } else if (r.data.error.NotFound != NULL) {
            printf("Error: NotFound(%s)\n", r.data.error.NotFound);
        } else {
            printf("Error: unknown variant\n");
        }
    } else {
        printf("%ld\n", r.data.value);
    }
}

int main() {
    int64_t test1[] = {1, 2, 3, 4, 5};
    Result_i64_LookupErr r1 = safeSum(test1, 5);
    print_result(r1);

    int64_t test2[] = {};
    Result_i64_LookupErr r2 = safeSum(test2, 0);
    print_result(r2);

    int64_t test3[] = {0, 0, 0, 0};
    Result_i64_LookupErr r3 = safeSum(test3, 4);
    print_result(r3);

    int64_t test4[] = {-10, 20, -30, 40};
    Result_i64_LookupErr r4 = safeSum(test4, 4);
    print_result(r4);

    int64_t test5[] = {1000000, 2000000, 3000000};
    Result_i64_LookupErr r5 = safeSum(test5, 3);
    print_result(r5);

    return 0;
}

