import java.util.*;

public class Solution {
    public static class LookupErr {
        public final String NotFound;
        public final Boolean EmptyCollection;

        private LookupErr(String NotFound, Boolean EmptyCollection) {
            this.NotFound = NotFound;
            this.EmptyCollection = EmptyCollection;
        }

        public static LookupErr fromNotFound(String msg) {
            return new LookupErr(msg, null);
        }

        public static LookupErr fromEmptyCollection() {
            return new LookupErr(null, true);
        }

        @Override
        public String toString() {
            if (EmptyCollection != null) {
                return "LookupErr{EmptyCollection=true}";
            } else {
                return "LookupErr{NotFound=" + NotFound + "}";
            }
        }
    }

    public static Object safeSum(int[] arr) {
        if (arr.length == 0) {
            return LookupErr.fromEmptyCollection();
        }

        int p = 0;
        int q = 0;
        while (q < arr.length) {
            p = p + arr[q];
            q = q + 1;
        }
        return p;
    }

    public static void main(String[] args) {
        // Test 1: Normal array with positive numbers
        int[] test1 = {1, 2, 3, 4, 5};
        Object result1 = safeSum(test1);
        System.out.println(result1 instanceof Integer ? result1 : result1);

        // Test 2: Empty array (should return error)
        int[] test2 = {};
        Object result2 = safeSum(test2);
        System.out.println(result2 instanceof Integer ? result2 : result2);

        // Test 3: Array with negative numbers
        int[] test3 = {-5, -3, 0, 2, 7};
        Object result3 = safeSum(test3);
        System.out.println(result3 instanceof Integer ? result3 : result3);

        // Test 4: Single element array
        int[] test4 = {42};
        Object result4 = safeSum(test4);
        System.out.println(result4 instanceof Integer ? result4 : result4);

        // Test 5: Array with zeros only
        int[] test5 = {0, 0, 0, 0};
        Object result5 = safeSum(test5);
        System.out.println(result5 instanceof Integer ? result5 : result5);
    }
}
